Commit:     John Bieling <john@thunderbird.net>
CommitDate: Thu Jan 23 14:49:18 2025 +0000

    Bug 1898585 - Auto-generate tag key if not provided. r=aleca


    Currently, `messages.tags.create()` requires specifying a tag name and a
    tag key. While this provides maximum flexibility, there are also
    scenarios where the add-on has no need to come up with a specific key or
    actually wants to use the exact same key that would be used if the tag
    is created through the UI.

    This patch makes the key parameter optional and returns the key
    associated with the created tag.

    Differential Revision: https://phabricator.services.mozilla.com/D235002

diff --git a/mail/components/extensions/parent/ext-messages.js b/mail/components/extensions/parent/ext-messages.js
index 1939ee75bfa..8a7af63ef5d 100644
--- a/mail/components/extensions/parent/ext-messages.js
+++ b/mail/components/extensions/parent/ext-messages.js
@@ -1366,7 +1366,10 @@ this.messages = class extends ExtensionAPIPersistent {
           return this.tags.list();
         },
         async createTag(key, tag, color) {
-          return this.tags.create(key, tag, color);
+          // browser.messages.tags.create() returns the associated key, but the
+          // deprecated method browser.messages.createTag() is not updated and
+          // should not return anything.
+          await this.tags.create(key, tag, color);
         },
         async updateTag(key, updateProperties) {
           return this.tags.update(key, updateProperties);
@@ -1390,14 +1393,22 @@ this.messages = class extends ExtensionAPIPersistent {
           },
           async create(key, tag, color) {
             const tags = MailServices.tags.getAllTags();
-            key = key.toLowerCase();
-            if (tags.find(t => t.key == key)) {
-              throw new ExtensionError(`Specified key already exists: ${key}`);
-            }
             if (tags.find(t => t.tag == tag)) {
               throw new ExtensionError(`Specified tag already exists: ${tag}`);
             }
-            MailServices.tags.addTagForKey(key, tag, color.toUpperCase(), "");
+            if (key != null) {
+              key = key.toLowerCase();
+              if (tags.find(t => t.key == key)) {
+                throw new ExtensionError(
+                  `Specified key already exists: ${key}`
+                );
+              }
+              MailServices.tags.addTagForKey(key, tag, color.toUpperCase(), "");
+            } else {
+              // Auto-generate a key.
+              MailServices.tags.addTag(tag, color.toUpperCase(), "");
+            }
+            return MailServices.tags.getKeyForTag(tag);
           },
           async update(key, updateProperties) {
             const tags = MailServices.tags.getAllTags();
diff --git a/mail/components/extensions/schemas/messages.json b/mail/components/extensions/schemas/messages.json
index 9ceae7104b8..38735ba8890 100644
--- a/mail/components/extensions/schemas/messages.json
+++ b/mail/components/extensions/schemas/messages.json
@@ -1396,14 +1396,15 @@
       {
         "name": "create",
         "type": "function",
-        "description": "Creates a new message tag. Tagging a message will store the tag's key in the user's message. Throws if the specified tag key is used already.",
+        "description": "Creates a new message tag and returns the associated key. Tagging a message will store the tag's key in the user's message. Throws if the specified tag key is used already.",
         "async": true,
         "permissions": ["messagesTags"],
         "parameters": [
           {
             "type": "string",
             "name": "key",
-            "description": "Unique tag identifier (will be converted to lower case). Must not include <var>()<>{/%*\"</var> or spaces.",
+            "optional": true,
+            "description": "Unique tag identifier (will be converted to lower case). Must not include <var>()<>{/%*\"</var> or spaces. Will be auto-generated if not provided.",
             "pattern": "^[^ ()/{%*<>\"]+$"
           },
           {
@@ -1416,6 +1417,17 @@
             "name": "color",
             "description": "Tag color in hex format (i.e.: #000080 for navy blue). Value will be stored as upper case.",
             "pattern": "^#[0-9a-fA-F]{6}"
+          },
+          {
+            "type": "function",
+            "name": "callback",
+            "optional": true,
+            "parameters": [
+              {
+                "type": "string",
+                "name": "key"
+              }
+            ]
           }
         ]
       },
diff --git a/mail/components/extensions/test/xpcshell/test_ext_messages.js b/mail/components/extensions/test/xpcshell/test_ext_messages.js
index aef9f032485..fd7b9a031d9 100644
--- a/mail/components/extensions/test/xpcshell/test_ext_messages.js
+++ b/mail/components/extensions/test/xpcshell/test_ext_messages.js
@@ -663,9 +663,46 @@ add_task(
           tags4
         );

+        // Test creating a tag without providing a key, auto-generating one.
+        const autoKey = await browser.messages.tags.create(
+          "Auto Tag",
+          "#3456CD"
+        );
+        browser.test.assertEq(
+          "auto_tag",
+          autoKey,
+          "Auto-generated key should be correct"
+        );
+
+        // Rename the auto-created tag.
+        await browser.messages.tags.update(autoKey, {
+          tag: "Something very different",
+        });
+        const autoTag = await browser.messages.tags
+          .list()
+          .then(rv => rv.find(t => t.key == autoKey));
+        browser.test.assertEq(
+          "Something very different",
+          autoTag.tag,
+          "The renamed tag should be correct"
+        );
+
+        // Test creating the same tag again and verify that a different auto-
+        // generated key is returned.
+        const autoKeyNr2 = await browser.messages.tags.create(
+          "Auto Tag",
+          "#1234AB"
+        );
+        browser.test.assertEq(
+          "auto_taga",
+          autoKeyNr2,
+          "Auto-generated key should be correct the second time as well"
+        );
+
         // Clean up.
         await browser.messages.update(folder4Messages[0].id, { tags: [] });
         await browser.messages.deleteTag("custom:_tag");
+        await browser.messages.deleteTag(autoKey);
         await browser.messages.tags.create("$label5", "Later", "#993399");
         browser.test.notifyPass("finished");
       },
@@ -681,6 +718,7 @@ add_task(
           "accountsRead",
           "messagesTags",
           "messagesUpdate",
+          "messagesTagsList",
         ],
